{
  "root_cause": "The datepicker, when shown, prevents default behavior on Tab keydown (likely via vanilla-calendar-pro's internal handlers), trapping focus in the departure date input and preventing tab navigation to the next form field.",
  "repair_strategy": "Add a capture-phase keydown listener for the Tab key on the input element that hides the datepicker when shown, without preventing default, allowing the browser to move focus naturally to the next field. The listener is registered in capture phase before VCP initializes, so it runs first and does not call preventDefault().",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void

  constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
    super(element, config)

    this._calendar = null
    this._isShown = false

    this._initCalendar()
  }",
      "after": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
  protected declare _onTabKey: (event: KeyboardEvent) => void

  constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
    super(element, config)

    this._calendar = null
    this._isShown = false

    // Add Tab key listener in capture phase to allow tabbing out of datepicker
    this._onTabKey = (event: KeyboardEvent) => {
      if (event.key === 'Tab' && this._isShown) {
        this.hide()
      }
    }
    this._element.addEventListener('keydown', this._onTabKey, true)

    this._initCalendar()
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }",
      "after": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    // Clean up Tab key listener
    this._element.removeEventListener('keydown', this._onTabKey, true)

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }"
    }
  ],
  "expected_accessibility_effect": "Tab key moves focus from the departure date field to the passengers field when the datepicker is open, matching standard form navigation behavior.",
  "functional_risks": [
    "Capture-phase listener runs before VCP handlers; if VCP also uses capture phase, order is not guaranteed.",
    "Hiding the datepicker on Tab may interrupt user interaction if they were navigating within the datepicker using Tab (though datepicker typically uses arrow keys).",
    "This fix only applies to non-inline datepickers attached to input elements; other configurations are unaffected."
  ],
  "verification_requirements": [
    "Verify that Tab key moves focus from the departure date to the passengers field when the datepicker is open.",
    "Verify that Escape key still closes the datepicker and allows tabbing out.",
    "Verify that Tabbing within the datepicker (if it contains focusable elements) does not unexpectedly close the datepicker.",
    "Verify that the datepicker still functions correctly for date selection when not using Tab."
  ]
}
